'use strict';

// MODULES //

var isObject = require( '@stdlib/assert/is-object' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var Compare = require( '@stdlib/plot/vega/mark/compare' );


// MAIN //

/**
* Tests whether an input value is an compare instance.
*
* @param {*} value - value to test
* @returns {boolean} boolean indicating whether an input value is an compare instance
*
* @example
* var Compare = require( '@stdlib/plot/vega/mark/compare' );
*
* var v = new Compare({
*     'field': 'amount'
* });
* var bool = isCompare( v );
* // returns true
*
* bool = isCompare( {} );
* // returns false
*
* bool = isCompare( 'foo' );
* // returns false
*/
function isCompare( value ) {
	return (
		value instanceof Compare ||

		// The following is a set of rather imperfect heuristics for handling instances originating in a different realm...
		(
			isObject( value ) &&
			isString( value.type ) &&
			isBoolean( value.resize ) &&
			isString( value.contains )
		)
	);
}


// EXPORTS //

module.exports = isCompare;
